        "name": "重力場／重力刀",
        "type": "",
        "description": "重力場於{chance|攻擊時 4.5%} 觸發，475 範圍普攻傷害 ×5＋45 萬物理，天賦後固定項提高至 55 萬。重力刀猛虎於{chance|攻擊時 15%} 觸發，475 範圍普攻傷害 ×2.5＋25 萬物理，單體另受 35 萬魔法傷害。兩招均使範圍敵人{control|暈眩 2.5 秒}。"
