        "description": "投入 4 點天賦強化天坑、重力場並取得隕石落下。攻擊破甲至少 40 的目標時，隕石對 675 範圍造成 12 萬{magic|魔法傷害} ×5＋100 萬{physical|物理傷害}，自身攻速 +100% 持續 5 秒。{important|絕對冷卻 5 秒}。"
